-- Pre-baked field actions retain each NPC's identity and avoid runtime baking.
for role,height in pairs{biker=141,['cue-ball']=120}do
 local base=catalog[role].styles.cobble
 local prefix='assets/'..role..'/cobble/bicycle-'
 base.actions={bicycle={runtime=base.runtime,atlas=prefix..'preview.png',humanCards={
  schema='ascendant.human-cards/v1',filter='nearest',cellWidth=256,cellHeight=224,
  anchorX=128,anchorY=220,referenceHeight=height,
  idle={sheet=prefix..'idle.png',columns=1,duration=1},
  walk={sheet=prefix..'walk.png',columns=12,duration=.96},
  blink={sheet=prefix..'blink.png',columns=4,duration=.24}}}}
end
return catalog
